package slug

import "strings"

// ============================================================
// Slug generation
// ============================================================

// Make converts a title into a URL slug.
func Make(title string) string {
	// lower-case everything first
	lowered := strings.ToLower(title)
	var b strings.Builder
	lastDash := false
	for _, r := range lowered {
		// fold a few accented letters we see in product names
		switch r {
		case 'é', 'è', 'ê':
			r = 'e'
		case 'à', 'â':
			r = 'a'
		case 'ö', 'ô':
			r = 'o'
		}
		// keep letters and digits
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			b.WriteRune(r)
			lastDash = false
		} else if !lastDash && b.Len() > 0 {
			// collapse runs of separators into one dash
			b.WriteRune('-')
			lastDash = true
		}
	}
	// old behaviour, kept for reference:
	// return strings.ReplaceAll(lowered, " ", "-")
	result := b.String()
	// strip a trailing dash
	if strings.HasSuffix(result, "-") {
		result = result[:len(result)-1]
	}
	return result
}

