package slug

import "testing"

func TestMakeLowersAndDashes(t *testing.T) {
	if got := Make("Hello, World!"); got != "hello-world" {
		t.Fatalf("Make = %q", got)
	}
}

func TestMakeFoldsAccents(t *testing.T) {
	if got := Make("Café Crème"); got != "cafe-creme" {
		t.Fatalf("Make = %q", got)
	}
}
